30	async function evaluate(testSuite: EvaluateTestSuite, options: EvaluateOptions = {}) {
31	  const constructedTestSuite: TestSuite = {
32	    ...testSuite,
33	    providers: await loadApiProviders(testSuite.providers, {
34	      env: testSuite.env,
35	    }),
36	    tests: await readTests(testSuite.tests),
37	
38	    nunjucksFilters: readFilters(testSuite.nunjucksFilters || {}),
39	
40	    // Full prompts expected (not filepaths)
41	    prompts: testSuite.prompts.map((promptInput) => {
42	      if (typeof promptInput === 'function') {
43	        return {
44	          raw: promptInput.toString(),
45	          display: promptInput.toString(),
46	          function: promptInput as PromptFunction,
47	        };
48	      } else if (typeof promptInput === 'string') {
49	        return {
50	          raw: promptInput,
51	          display: promptInput,
52	        };
53	      } else {
54	        return {
55	          raw: JSON.stringify(promptInput),
56	          display: JSON.stringify(promptInput),
57	        };
58	      }
59	    }),
60	  };
61	
62	  // Resolve nested providers
63	  for (const test of constructedTestSuite.tests || []) {
64	    if (test.options?.provider && typeof test.options.provider === 'function') {
65	      test.options.provider = await loadApiProvider(test.options.provider);
66	    }
67	    if (test.assert) {
68	      for (const assertion of test.assert) {
69	        if (assertion.provider) {
70	          if (typeof assertion.provider === 'object') {
71	            const casted = assertion.provider as ProviderOptions;
72	            invariant(casted.id, 'Provider object must have an id');
73	            assertion.provider = await loadApiProvider(casted.id, { options: casted });
74	          } else if (typeof assertion.provider === 'string') {
75	            assertion.provider = await loadApiProvider(assertion.provider);
76	          } else {
77	            // It's a function, no need to do anything
78	          }
79	        }
80	      }
81	    }
82	  }
83	
84	  // Other settings
85	  if (options.cache === false || (options.repeat && options.repeat > 1)) {
86	    disableCache();
87	  }
88	  telemetry.maybeShowNotice();
89	
90	  // Run the eval!
91	  const ret = await doEvaluate(constructedTestSuite, {
92	    eventSource: 'library',
93	    ...options,
94	  });
95	
96	  if (testSuite.outputPath) {
97	    if (typeof testSuite.outputPath === 'string') {
98	      writeOutput(testSuite.outputPath, ret, testSuite, null);
99	    } else if (Array.isArray(testSuite.outputPath)) {
100	      writeMultipleOutputs(testSuite.outputPath, ret, testSuite, null);
101	    }
102	  }
103	
104	  if (testSuite.writeLatestResults) {
105	    await migrateResultsFromFileSystemToDatabase();
106	    await writeResultsToDatabase(ret, testSuite);
107	  }
108	
109	  await telemetry.send();
110	  return ret;
111	}
